package com.nunnun.roommate.entity;
import com.nunnun.user.entity.User; import jakarta.persistence.*; import java.time.LocalDateTime; import java.util.Objects; import org.springframework.data.annotation.CreatedDate; import org.springframework.data.jpa.domain.support.AuditingEntityListener;
@Entity @Table(name="roommate_groups") @EntityListeners(AuditingEntityListener.class)
public class RoommateGroup { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,length=50) private String name; @Column(name="invite_code",unique=true,length=20) private String inviteCode; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="creator_id") private User creator; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private RoommateGroupStatus status; @CreatedDate @Column(name="created_at",nullable=false,updatable=false) private LocalDateTime createdAt; protected RoommateGroup(){} private RoommateGroup(String n,String c,User u){name=Objects.requireNonNull(n);inviteCode=Objects.requireNonNull(c);creator=Objects.requireNonNull(u);status=RoommateGroupStatus.WAITING;} public static RoommateGroup create(String n,String c,User u){return new RoommateGroup(n,c,u);} public void activate(){status=RoommateGroupStatus.ACTIVE;} public void waitForRoommate(){status=RoommateGroupStatus.WAITING;} public Long getId(){return id;} public String getName(){return name;} public String getInviteCode(){return inviteCode;} public User getCreator(){return creator;} public RoommateGroupStatus getStatus(){return status;} }
